#!/usr/bin/env bash
set -euo pipefail
ROOT="${1:-$(pwd)}"
cd "$ROOT"
die(){ echo "ERROR: $*" >&2; exit 1; }
git rev-parse --is-inside-work-tree >/dev/null 2>&1 || die "Run inside the Magic_Earth repo"
[[ "$(git rev-parse --abbrev-ref HEAD)" == "main" ]] || die "Must be on main"
[[ -z "$(git status --porcelain)" ]] || die "Repo is not clean; commit/stash first"
git pull --ff-only origin main

python3 - <<'PYFILES'
from pathlib import Path
import base64
files = {
    'tools/drive_ready_repo_transform.py': '',
    'drive_ready_corridor_selftest.mjs': '',
    'ci/drive_ready_live_probe.py': '',
    'ci/drive_ready_live_match.mjs': '',
    '.github/workflows/drive-ready-r2.yml': '',
}
for name,b64 in files.items():
    p=Path(name); p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(base64.b64decode(b64))
Path('tools/drive_ready_repo_transform.py').chmod(0o755)
Path('ci/drive_ready_live_probe.py').chmod(0o755)
print('Drive-ready R2 support files written')
PYFILES

python3 tools/drive_ready_repo_transform.py "$ROOT"

echo '==> Local exact simulations / checks'
node --check payload/cairodrive-google-search-only.js
node search_core_selftest.mjs
node traffic_core_selftest.mjs
node drive_ready_corridor_selftest.mjs
bash -n verify_patcher.sh
bash -n VERIFY_REPO.sh
./verify_patcher.sh
./VERIFY_REPO.sh
git diff --check

echo '==> Commit and push'
git add payload/cairodrive-google-search-only.js verify_patcher.sh VERIFY_REPO.sh \
  tools/drive_ready_repo_transform.py drive_ready_corridor_selftest.mjs \
  ci/drive_ready_live_probe.py ci/drive_ready_live_match.mjs \
  .github/workflows/drive-ready-r2.yml
git commit -m "Harden drive-ready search traffic simulation and smoothness"
git push origin main

echo
echo 'DRIVE-READY R2 LOCAL PATCH: PASS'
echo 'GitHub will now run the live Google Cairo probe and canonical signed build automatically.'
